def __new__(mcs, name, bases, namespace, **kwargs):
    # pydantic 2 makes `Optional[T]` fields without a default required. ConfZ
    # keeps the previous behaviour where such fields default to `None`.
    annotations = namespace.get("__annotations__", {})
    module = sys.modules.get(namespace.get("__module__", ""))
    module_globals = vars(module) if module is not None else {}
    for field_name, annotation in annotations.items():
        if field_name not in namespace and _is_optional_annotation(
            annotation, module_globals
        ):
            namespace[field_name] = None
    return super().__new__(mcs, name, bases, namespace, **kwargs)

